  db.prepare('INSERT INTO certificados (codigo, atividadeId, participanteId, cargaHorariaMinutos, presencas, encontros, emitidoEm) VALUES (?, ?, ?, ?, ?, ?, ?)').run('SA26-CCCC-DDDD', 'atv_old', 'p-carla', 60, 1, 1, '2026-10-20T20:00:00-03:00');
  console.log('linhas com dup:', db.prepare('SELECT COUNT(*) AS t FROM certificados').get().t);
  db.close();
}

let falhou = false;
try {
  const banco = novoBanco(caminho);
  banco.close();
} catch (e) {
  falhou = true;
  console.log('novoBanco reportou:', e.code, '-', e.message.split('\n')[0]);
}

const conf = new Database(caminho, { readonly: true });
const linhas = conf.prepare('SELECT codigo FROM certificados ORDER BY codigo').all();
console.log('linhas preservadas:', JSON.stringify(linhas.map((r) => r.codigo)));
conf.close();
if (!falhou) throw new Error('era esperado que a criação do índice falhasse com duplicatas');
if (linhas.length !== 2) throw new Error('dados foram apagados — não deveria apagar');
console.log('DUP-REPORTADA-SEM-APAGAR OK');

